def main():
    sys._reversion_source_directory = Path(__file__).resolve().parent
    with tempfile.TemporaryDirectory(prefix="reversion-lab-") as directory:
        with zipfile.ZipFile(io.BytesIO(base64.b64decode(_PAYLOAD))) as archive:
            archive.extractall(directory)
        sys.path.insert(0, directory)
        try:
            runpy.run_path(str(Path(directory) / "app.py"), run_name="__main__")
        finally:
            sys.path.remove(directory)

if __name__ == "__main__":
    main()
